def tribonacci(n):
    result = []
    if n == 1:
        result.append(3)
    else:
        a, b = 0, 3
        for _ in range(n + 1):
            if a % 2 == 1:
                c = a // 2 if a % 2 == 0 else a // 2 + 1
                d = b if a % 2 == 0 else b + c
                result.append(d)
                a, b = b, d
            else:
                result.append(a // 2 if a % 2 == 0 else a // 2 + 1)
    return result

print(tribonacci(3))  # [1, 3, 2, 8]
